import type { Metadata, Viewport } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import Link from "next/link";

import { asset, canonical, origin, profile, site } from "@/lib/site";
import "./globals.css";

const geistSans = Geist({ variable: "--font-geist-sans", subsets: ["latin"], display: "swap" });
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"], display: "swap" });

/**
 * Generated by `npm run og`, which the build runs, so the card cannot drift
 * from `content/profile.json`. A real `.png` in `public/` rather than Next's
 * `opengraph-image` convention: that emits an extensionless file, and GitHub
 * Pages types unknown extensions as `application/octet-stream`, which the
 * social scrapers reject.
 */
const card = {
  url: asset("og.png"),
  width: 1200,
  height: 630,
  alt: `${profile.name} — ${profile.tagline}`,
};

export const metadata: Metadata = {
  // Origin only — Next applies `basePath` on top of this itself.
  metadataBase: new URL(origin),
  title: { default: site.title, template: `%s · ${site.name}` },
  description: site.description,
  alternates: { canonical: canonical("/") },
  authors: [{ name: profile.name }],
  creator: profile.name,
  openGraph: {
    type: "website",
    siteName: site.name,
    locale: site.locale,
    url: canonical("/"),
    title: site.title,
    description: site.description,
    images: [card],
  },
  twitter: {
    card: "summary_large_image",
    title: site.title,
    description: site.description,
    images: [card.url],
  },
};

export const viewport: Viewport = {
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#fcfbf9" },
    { media: "(prefers-color-scheme: dark)", color: "#121110" },
  ],
};

const NAV = [
  { href: "/", label: "Home" },
  { href: "/projects/", label: "Projects" },
  { href: "/about/", label: "About" },
];

export default function RootLayout({ children }: { children: React.ReactNode }) {
  // Compiled away in production: `process.env.NODE_ENV` is inlined, so the
  // admin link does not exist in the exported HTML at all.
  const dev = process.env.NODE_ENV !== "production";

  return (
    <html lang="en">
      <body className={`${geistSans.variable} ${geistMono.variable} font-sans min-h-dvh flex flex-col`}>
        <a
          href="#main"
          className="sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-50 focus:rounded focus:bg-surface focus:px-3 focus:py-2 focus:text-sm"
        >
          Skip to content
        </a>

        <header className="border-b border-line">
          <nav
            aria-label="Main"
            className="mx-auto flex max-w-3xl items-center gap-6 px-6 py-4 text-sm"
          >
            {NAV.map((item) => (
              <Link key={item.href} href={item.href} className="hover:text-accent">
                {item.label}
              </Link>
            ))}
            <span className="grow" />
            {dev ? (
              <Link href="/admin/" className="text-muted hover:text-accent">
                Admin
              </Link>
            ) : null}
          </nav>
        </header>

        <main id="main" className="mx-auto w-full max-w-3xl grow px-6 py-12">
          {children}
        </main>
      </body>
    </html>
  );
}
